DROP TABLE IF EXISTS `login_usersessionsettings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `login_usersessionsettings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `inactivity_timeout_minutes` smallint unsigned NOT NULL,
  `user_id` int NOT NULL,
  `last_activity_at` datetime(6) DEFAULT NULL,
  `password_changed_at` datetime(6) NOT NULL,
  `password_never_expires` tinyint(1) NOT NULL,
  `failed_login_attempts` smallint unsigned NOT NULL,
  `locked_until` datetime(6) DEFAULT NULL,
  `mfa_activa` tinyint(1) NOT NULL,
  `mfa_codigos_respaldo` json NOT NULL DEFAULT (_utf8mb4'[]'),
  `mfa_requerida` tinyint(1) NOT NULL,
  `mfa_secreto` varchar(64) NOT NULL,
  `mfa_ultimo_paso` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  CONSTRAINT `login_usersessionsettings_user_id_12e4e6db_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `login_usersessionsettings_chk_1` CHECK ((`inactivity_timeout_minutes` >= 0)),
  CONSTRAINT `login_usersessionsettings_chk_2` CHECK ((`failed_login_attempts` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
