--
-- Table structure for table `medicion`
--

DROP TABLE IF EXISTS `medicion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `medicion` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sensor_id` bigint unsigned NOT NULL,
  `evento_id` char(36) NOT NULL COMMENT 'UUID del evento para idempotencia.',
  `temperatura` decimal(5,2) DEFAULT NULL,
  `humedad` decimal(5,2) DEFAULT NULL,
  `fecha_hora_medicion` datetime NOT NULL COMMENT 'UTC (RNF-INT-02). Marca de tiempo del sensor.',
  `fecha_hora_recepcion` datetime NOT NULL COMMENT 'UTC (RNF-INT-02). Marca de tiempo de recepcion.',
  `origen` enum('Real','Simulado') NOT NULL DEFAULT 'Real',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_medicion_sensor_evento` (`sensor_id`,`evento_id`),
  KEY `idx_medicion_sensor_fecha` (`sensor_id`,`fecha_hora_medicion`),
  KEY `idx_medicion_fecha` (`fecha_hora_medicion`),
  CONSTRAINT `fk_medicion_sensor` FOREIGN KEY (`sensor_id`) REFERENCES `sensor` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=6269 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SOLO INSERCION (inmutable). La capa de datos DEBE impedir UPDATE/DELETE via permisos (GRANT solo INSERT/SELECT). Idempotencia por UNIQUE(sensor_id, evento_id). Alto volumen: hasta 43.200 registros/sensor/dia -> ver particionamiento sugerido al final.';
/*!40101 SET character_set_client = @saved_cs_client */;

