--
-- Table structure for table `notificacion`
--

DROP TABLE IF EXISTS `notificacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notificacion` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `alerta_id` bigint unsigned DEFAULT NULL,
  `intervencion_id` bigint unsigned DEFAULT NULL,
  `canal` enum('SMTP','PowerAutomate') NOT NULL,
  `destinatario` varchar(255) NOT NULL,
  `fecha_envio` datetime NOT NULL COMMENT 'UTC (RNF-INT-02)',
  `resultado` enum('Enviado','Fallido') NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_notif_alerta` (`alerta_id`),
  KEY `idx_notif_intervencion` (`intervencion_id`),
  KEY `idx_notif_resultado` (`resultado`),
  CONSTRAINT `fk_notif_alerta` FOREIGN KEY (`alerta_id`) REFERENCES `alerta` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_notif_intervencion` FOREIGN KEY (`intervencion_id`) REFERENCES `intervencion` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=184 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Notificaciones emitidas por alerta o intervencion. FKs opcionales SET NULL.';
/*!40101 SET character_set_client = @saved_cs_client */;

