DROP TABLE IF EXISTS `permiso_acceso`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `permiso_acceso` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `persona_id` bigint unsigned NOT NULL,
  `punto_acceso_id` bigint unsigned NOT NULL,
  `vigencia_inicio` date NOT NULL,
  `vigencia_fin` date DEFAULT NULL,
  `estado` enum('Activo','Revocado') NOT NULL DEFAULT 'Activo',
  PRIMARY KEY (`id`),
  KEY `idx_permiso_persona` (`persona_id`),
  KEY `idx_permiso_punto` (`punto_acceso_id`),
  KEY `idx_permiso_estado` (`estado`),
  CONSTRAINT `fk_permiso_persona` FOREIGN KEY (`persona_id`) REFERENCES `persona_autorizada` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_permiso_punto` FOREIGN KEY (`punto_acceso_id`) REFERENCES `punto_acceso` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Permiso de acceso de una persona a un punto de acceso.';
/*!40101 SET character_set_client = @saved_cs_client */;

