DROP TABLE IF EXISTS `permiso_dia`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `permiso_dia` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `permiso_acceso_id` bigint unsigned NOT NULL,
  `dia_semana` enum('Lun','Mar','Mie','Jue','Vie','Sab','Dom') NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fin` time NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_permiso_dia_permiso` (`permiso_acceso_id`),
  CONSTRAINT `fk_permiso_dia_permiso` FOREIGN KEY (`permiso_acceso_id`) REFERENCES `permiso_acceso` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Ventanas horarias por dia de un permiso de acceso. CASCADE: se elimina con el permiso padre.';
