--
-- Table structure for table `persona_autorizada`
--

DROP TABLE IF EXISTS `persona_autorizada`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `persona_autorizada` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) NOT NULL,
  `identificador_biometrico_externo` varchar(255) NOT NULL,
  `estado` enum('Activo','Inactivo') NOT NULL DEFAULT 'Activo',
  `usuario_id` int DEFAULT NULL,
  `rut` varchar(12) DEFAULT NULL,
  `empresa` varchar(150) DEFAULT NULL,
  `huella_registrada_en` datetime DEFAULT NULL COMMENT 'UTC',
  `huella_registrada_por_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_persona_biometrico` (`identificador_biometrico_externo`),
  UNIQUE KEY `uq_persona_rut` (`rut`),
  KEY `idx_persona_usuario` (`usuario_id`),
  KEY `fk_persona_huella_por` (`huella_registrada_por_id`),
  CONSTRAINT `fk_persona_huella_por` FOREIGN KEY (`huella_registrada_por_id`) REFERENCES `auth_user` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_persona_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `auth_user` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Personas autorizadas (identificador biometrico externo, sin datos biometricos crudos).';
/*!40101 SET character_set_client = @saved_cs_client */;

