  `posicion` varchar(100) DEFAULT NULL,
  `ubicacion_padre_id` bigint unsigned DEFAULT NULL,
  `activa` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Baja logica (RN-02)',
  PRIMARY KEY (`id`),
  KEY `idx_ubicacion_padre` (`ubicacion_padre_id`),
